  @snap_edges           = hash[:snap_edges]
  @still_reflections    = hash[:still_reflections]
  @random_dungeon       = hash[:random_dungeon]
  @battle_background    = hash[:battle_background]
  @wild_battle_BGM      = hash[:wild_battle_BGM]
  @trainer_battle_BGM   = hash[:trainer_battle_BGM]
  @wild_victory_BGM     = hash[:wild_victory_BGM]
  @trainer_victory_BGM  = hash[:trainer_victory_BGM]
  @wild_capture_ME      = hash[:wild_capture_ME]
  @town_map_size        = hash[:town_map_size]
  @battle_environment   = hash[:battle_environment]
  @flags                = hash[:flags]           || []
  @pbs_file_suffix      = hash[:pbs_file_suffix] || ""
end

def pbStartScreen(pokemon, pokemon2, trader1, trader2)
  @sprites = {}
  @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @viewport.z = 99999
  @pokemon  = pokemon
  @pokemon2 = pokemon2
  @trader1  = trader1
  @trader2  = trader2
  addBackgroundOrColoredPlane(@sprites, "background", "trade_bg",
                              Color.new(248, 248, 248), @viewport)
  @sprites["rsprite1"] = PokemonSprite.new(@viewport)
  @sprites["rsprite1"].setPokemonBitmap(@pokemon, false)
  @sprites["rsprite1"].setOffset(PictureOrigin::BOTTOM)
  @sprites["rsprite1"].x = Graphics.width / 2
  @sprites["rsprite1"].y = 264
  @sprites["rsprite1"].z = 10
  @pokemon.species_data.apply_metrics_to_sprite(@sprites["rsprite1"], 1)
  @sprites["rsprite2"] = PokemonSprite.new(@viewport)
  @sprites["rsprite2"].setPokemonBitmap(@pokemon2, false)
  @sprites["rsprite2"].setOffset(PictureOrigin::BOTTOM)
  @sprites["rsprite2"].x = Graphics.width / 2
  @sprites["rsprite2"].y = 264
  @sprites["rsprite2"].z = 10
  @pokemon2.species_data.apply_metrics_to_sprite(@sprites["rsprite2"], 1)
  @sprites["rsprite2"].visible = false
  @sprites["msgwindow"] = pbCreateMessageWindow(@viewport)
  pbFadeInAndShow(@sprites)
end

def pbEvolutionMethodAfterEvolution
  @pokemon.action_after_evolution(@newspecies)
end

def pbEndScreen(need_fade_out = true)
  pbDisposeMessageWindow(@sprites["msgwindow"]) if @sprites["msgwindow"]
  if need_fade_out
    pbFadeOutAndHide(@sprites) { pbUpdate }
  end
  pbDisposeSpriteHash(@sprites)
  @viewport.dispose
  @bgviewport.dispose
  @msgviewport.dispose
end

def hp=(value)
  @hp = value.clamp(0, @totalhp)
  heal_status if @hp == 0
  @ready_to_evolve = false if @hp == 0
end

def pokemon_party
  return @party.find_all { |p| p && !p.egg? }
end

def able_party
  return @party.find_all { |p| p && !p.egg? && !p.fainted? }
end

def pbChooseAblePokemon(variableNumber, nameVarNumber)
  pbChoosePokemon(variableNumber, nameVarNumber, proc { |pkmn| !pkmn.egg? && pkmn.hp > 0 })
end

def pbChoosePokemonForTrade(variableNumber, nameVarNumber, wanted)
  wanted = GameData::Species.get(wanted).species
  pbChooseTradablePokemon(variableNumber, nameVarNumber, proc { |pkmn|
    next pkmn.species == wanted
  })
end

